import { useState } from "react";
import {
    Box,
    IconButton,
    Typography,
    Menu,
    MenuItem,
    ListItemIcon,
    ListItemText,
    Divider,
} from "@mui/material";

import {
    ArrowBack,
    ArrowForward,
    Refresh,
    MoreVert,
    ContentCopy,
    Check,
    Remove,
    Add,
} from "@mui/icons-material";

const ZOOM_MIN = 0.5;
const ZOOM_MAX = 1.5;

export default function NavigationBar({
    content,
    colors,
    onRefresh = () => {},
    zoomLevel = 1,
    onZoomIn = () => {},
    onZoomOut = () => {},
}) {
    const [anchorEl, setAnchorEl] = useState(null);
    const [copied, setCopied] = useState(false);
    const menuOpen = Boolean(anchorEl);

    const handleMenuOpen = (e) => {
        setAnchorEl(e.currentTarget);
    };

    const handleMenuClose = () => {
        setAnchorEl(null);
        setCopied(false);
    };

    const handleCopyLink = async () => {
        try {
            await navigator.clipboard.writeText(content.pageUrl || "");
            setCopied(true);
            setTimeout(() => setCopied(false), 1200);
        } catch (err) {
            console.error("Failed to copy link", err);
        }
    };

    const zoomMinned = zoomLevel <= ZOOM_MIN;
    const zoomMaxed = zoomLevel >= ZOOM_MAX;

    return (
        <Box
            sx={{
                display: "flex",
                alignItems: "center",
                px: 1,
                py: 0.5,
                // borderBottom: `1px solid ${colors.brd}`,
            }}
        >
            {/* Left navigation icons */}
            <IconButton
                sx={{ color: colors.btns }}
                size="small"
            >
                <ArrowBack fontSize="small" />
            </IconButton>
            <IconButton
                sx={{ color: colors.btns }}
                size="small"
            >
                <ArrowForward fontSize="small" />
            </IconButton>
            <IconButton
                sx={{ color: colors.btns }}
                size="small"
                onClick={onRefresh}
            >
                <Refresh fontSize="small" />
            </IconButton>

            {/* Address bar */}
            <Box
                sx={{
                    flexGrow: 1,
                    mx: 1,
                    px: 2,
                    py: 0.5,
                    backgroundColor: "white",
                    borderRadius: 100,
                    border: `1px solid ${colors.brd}`,
                    display: "flex",
                    alignItems: "center",
                    overflow: "hidden",
                    pointerEvents: "auto",
                }}
            >
                <Typography
                    variant="body2"
                    color="text.secondary"
                    noWrap
                >
                    {content.pageUrl || "https://website.com"}
                </Typography>
            </Box>

            {/* Right navigation icons */}
            <IconButton
                sx={{ color: colors.btns }}
                size="small"
                onClick={handleMenuOpen}
            >
                <MoreVert fontSize="small" />
            </IconButton>
            {dropdownMenu({
                menuOpen,
                anchorEl,
                handleMenuClose,
                handleCopyLink,
                copied,
                onZoomIn,
                onZoomOut,
                zoomLevel,
                zoomMinned,
                zoomMaxed,
            })}
        </Box>
    );
}

function dropdownMenu({
    menuOpen,
    anchorEl,
    handleMenuClose,
    handleCopyLink,
    copied,
    onZoomIn,
    onZoomOut,
    zoomLevel,
    zoomMinned,
    zoomMaxed,
}) {
    return (
        <Menu
            anchorEl={anchorEl}
            open={menuOpen}
            onClose={handleMenuClose}
            anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
            transformOrigin={{ vertical: "top", horizontal: "right" }}
        >
            {/* Chrome-style zoom row: - / percentage / + */}
            <MenuItem onClick={handleCopyLink}>
                <ListItemIcon>
                    {copied ? (
                        <Check fontSize="small" />
                    ) : (
                        <ContentCopy fontSize="small" />
                    )}
                </ListItemIcon>
                <ListItemText>{copied ? "Copied!" : "Copy link"}</ListItemText>
            </MenuItem>
            {/* <Divider /> */}
            <Box
                sx={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 1,
                    px: 2,
                    py: 0.5,
                }}
            >
                <IconButton
                    size="small"
                    onClick={onZoomOut}
                    disabled={zoomMinned}
                    sx={{
                        "&:hover": {
                            backgroundColor: "#444444",
                        },
                    }}
                >
                    <Remove fontSize="small" />
                </IconButton>
                <Typography
                    variant="body2"
                    sx={{ minWidth: 44, textAlign: "center" }}
                >
                    Zoom {Math.round(zoomLevel * 100)}%
                </Typography>
                <IconButton
                    size="small"
                    onClick={onZoomIn}
                    disabled={zoomMaxed}
                    sx={{
                        "&:hover": {
                            backgroundColor: "#444444",
                        },
                    }}
                >
                    <Add fontSize="small" />
                </IconButton>
            </Box>
        </Menu>
    );
}
