import { Typography, Box } from "@mui/material";
import { useEffect, useState } from "react";

export default function ChromeViewport({
    content,
    maximized,
    onLoad,
    refreshKey = 0,
    zoomLevel = 1,
}) {
    const [delayedMaximized, setDelayedMaximized] = useState(false);

    useEffect(() => {
        if (!maximized) {
            setDelayedMaximized(false);
        } else {
            const timer = setTimeout(() => setDelayedMaximized(maximized), 500);
            return () => clearTimeout(timer);
        }
    }, [maximized]);

    return (
        <>
            {/* {delayedMaximized ? (
                <iframe
                    src={`${content.pageUrl}`}
                    style={{
                        width: "100%",
                        height: "101%",
                        minHeight: "50vh",
                        // pointerEvents: active ? "auto" : "none",
                        scrolling: "no",
                        border: "none",
                    }}
                    title={content.title}
                    onLoad={() => onLoad(true)}
                />
            ) : (
                <img
                    src={`/img/desktop/${content.imgUrl}`}
                    alt={content.title}
                    draggable={false}
                    onLoad={() => onLoad(true)}
                    style={{
                        maxWidth: "100%",
                        maxHeight: "100%",
                        objectFit: "contain",
                    }}
                />
            )} */}

            {!maximized ? (
                <img
                    src={`/img/desktop/${content.imgUrl}`}
                    alt={content.title}
                    draggable={false}
                    onLoad={() => onLoad(true)}
                    style={{
                        maxWidth: "100%",
                        maxHeight: "100%",
                        objectFit: "contain",
                    }}
                />
            ) : delayedMaximized ? (
                <div
                    style={{
                        width: "100%",
                        height: "101%",
                        minHeight: "50vh",
                        overflow: "hidden",
                        position: "relative",
                    }}
                >
                    <iframe
                        // key forces a full remount on refresh, reloading
                        // the iframe from its original src and discarding
                        // any in-frame navigation/state
                        key={refreshKey}
                        src={`${content.pageUrl}`}
                        style={{
                            width: `${100 / zoomLevel}%`,
                            height: `${100 / zoomLevel}%`,
                            // pointerEvents: active ? "auto" : "none",
                            scrolling: "no",
                            border: "none",
                            transform: `scale(${zoomLevel})`,
                            transformOrigin: "0 0",
                            transition: "transform 0.2s ease",
                        }}
                        title={content.title}
                        onLoad={() => onLoad(true)}
                    />
                </div>
            ) : null}
        </>
    );
}
