import { Box, Typography } from "@mui/material";
import { AnimatePresence, motion } from "framer-motion";

import ControlBar from "./ControlBar";
import NavigationBar from "./NavigationBar";

export default function Header({
    type,
    platform,
    colors,
    isMobile,
    maximized,
    setMaximized,
    content,
    active,
    closed,
    setClosed,
    minimized,
    setMinimized,
    onRefresh,
    zoomLevel,
    onZoomIn,
    onZoomOut,
}) {
    return (
        <Box
            sx={{
                backdropFilter: minimized ? "blur(15px)" : "blur(50px)",
                px: minimized || closed ? 2 : "auto",
                py: minimized || closed ? 1 : "auto",
                backgroundColor:
                    closed || (isMobile && active) ? "black" : "auto",
                color:
                    closed || (isMobile && active)
                        ? "rgba(255, 255, 255, 1)"
                        : // : "rgba(255, 255, 255, 1)",
                          "rgba(50, 50, 50, 1)",
                transition: "all 0.3s ease",
                mixBlendMode: closed || (isMobile && active) ? "none" : "none",
            }}
            className="drag-handle"
        >
            {closed || minimized ? (
                <Typography>{content.title}</Typography>
            ) : (
                <>
                    <ControlBar
                        platform={platform}
                        colors={colors}
                        setMaximized={setMaximized}
                        setClosed={setClosed}
                        setMinimized={setMinimized}
                    />

                    {content.type == "web" && (
                        <div
                            style={{
                                position: "relative",
                                overflowY: "hidden",
                                pointerEvents: "auto",
                                maxHeight: maximized ? "100px" : "0px",
                                width: "100%",
                                transition: "all 1s ease-in-out",
                                borderBottom: `0.1px solid ${colors.brd}`,
                            }}
                        >
                            <NavigationBar
                                content={content}
                                colors={colors}
                                onRefresh={onRefresh}
                                zoomLevel={zoomLevel}
                                onZoomIn={onZoomIn}
                                onZoomOut={onZoomOut}
                            />
                        </div>
                    )}
                </>
            )}
        </Box>
    );
}
